// Word timings are local to the subtitle, not automatic musical beat detection.
function installKaraokeEditor(dialog,clip,onPreview){
  const M=LQTACSubtitleModel,original=JSON.parse(clip.dataset.subtitleStyle||'{}').karaoke;
  let text=$('#subText').value,words=structuredClone(original?.words||M.seedWords(text,clipTiming(clip).durationSeconds)),offset=original?.offset||0,next=0,frame=0,closed=false,dragCleanup=null;
  const box=document.createElement('fieldset');box.id='karaokeEditor';box.innerHTML='<legend>Karaoke</legend><div class="sub-grid"><label>Modo<select id="karaokeMode"><option value="normal">Subtítulo normal</option><option value="word">Resaltar por palabra</option><option value="progressive">Relleno progresivo</option></select></label><label>Color cantado<input id="karaokeColor" type="color" value="#ffd54f"></label></div><div id="karaokeTiming"><p>El color habitual es el texto pendiente. Los tiempos iniciales son un reparto orientativo, no una detección del canto. Ajusta escuchando el proyecto. Los tiempos son segundos desde el inicio del bloque.</p><button type="button" id="karaokeSpread">Repartir tiempos</button> <button type="button" id="karaokeListen">▶ Escuchar proyecto</button> <button type="button" id="karaokeMark">Marcar siguiente palabra</button><label>Posición <input id="karaokeSeek" type="range" min="0" step="0.001" value="0"><output id="karaokeClock"></output></label><div id="karaokeLane" aria-label="Tiempos de palabras"></div><div class="karaoke-table"><table><thead><tr><th>Palabra</th><th>Inicio (s)</th><th>Fin (s)</th></tr></thead><tbody id="karaokeWords"></tbody></table></div><p id="karaokeError" role="status"></p></div>';
  const grid=$('.sub-grid',dialog),top=document.createElement('div'),left=document.createElement('div'),right=document.createElement('div'),details=document.createElement('details'),summary=document.createElement('summary'),styleGrid=document.createElement('div');
  top.className='karaoke-editor-top';styleGrid.className='sub-grid';summary.textContent='Tipografía, colores y posición';details.append(summary,styleGrid);[...grid.children].slice(2).forEach(label=>styleGrid.append(label));
  $('h2',dialog).after(top);left.append($('#subText'),grid);right.append($('#subPreview'),details);top.append(left,right);top.after(box);
  const css=document.createElement('style');css.textContent='#subtitleDialog{max-height:92vh;overflow:auto}#karaokeEditor{border:1px solid #355078;margin:12px 0;padding:12px}#karaokeEditor button{margin:4px 0}#karaokeSeek{width:75%;max-width:none!important}.karaoke-table{max-height:165px;overflow:auto}.karaoke-table table{width:100%;text-align:left}.karaoke-table input{width:100px}#karaokeLane{height:54px;background:#07192f;position:relative;margin:12px 0;overflow:hidden;touch-action:none}.karaoke-word{position:absolute;top:8px;height:34px;background:#214876;border:1px solid #6acde5;box-sizing:border-box;color:white;cursor:grab;overflow:hidden;white-space:nowrap;font-size:11px;min-width:2px}.karaoke-word b{position:absolute;top:0;bottom:0;width:7px;background:#6acde5;cursor:ew-resize}.karaoke-word b[data-edge=start]{left:0}.karaoke-word b[data-edge=end]{right:0}.karaoke-word span{padding:0 9px;pointer-events:none}';box.append(css);
  css.textContent+='.karaoke-editor-top{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start}#subtitleDialog .sub-grid label{margin:4px 0;gap:6px}#subtitleDialog details summary{cursor:pointer;color:#7fcfe9;margin:8px 0}#subtitleDialog .karaoke-editor-top .sub-grid{grid-template-columns:1fr}#karaokeEditor .sub-grid select{width:190px;max-width:100%}@media(max-width:700px){.karaoke-editor-top{grid-template-columns:1fr}}';
  $('#karaokeMode').value=original?.mode||'normal';$('#karaokeColor').value=original?.color||'#ffd54f';
  const duration=()=>Math.max(.001,Number($('#subDuration').value)||.001),position=()=>Number($('#karaokeSeek').value)||0;
  const repaint=()=>{if(!closed)onPreview();};
  function lane(){const d=duration(),host=$('#karaokeLane'),list=M.words(text);host.replaceChildren();words.forEach((w,i)=>{if(w.end<=offset||w.start>=offset+d)return;const el=document.createElement('div');el.className='karaoke-word';el.dataset.index=i;el.style.left=(Math.max(0,w.start-offset)/d*100)+'%';el.style.width=((Math.min(d,w.end-offset)-Math.max(0,w.start-offset))/d*100)+'%';const label=document.createElement('span');label.textContent=list[i];el.title=label.textContent;el.append(label);for(const edge of ['start','end']){const h=document.createElement('b');h.dataset.edge=edge;el.append(h);}host.append(el);});}
  function rows(){const list=M.words(text),body=$('#karaokeWords');body.replaceChildren();words.forEach((w,i)=>{const tr=document.createElement('tr'),label=document.createElement('td');label.textContent=list[i];tr.append(label);for(const edge of ['start','end']){const td=document.createElement('td'),input=document.createElement('input');input.type='number';input.step='.001';input.value=Number((w[edge]-offset).toFixed(3));input.dataset.index=i;input.dataset.edge=edge;input.setAttribute('aria-label',list[i]+' '+edge);td.append(input);tr.append(td);}body.append(tr);});lane();}
  function value(){const same=original&&JSON.stringify(words)===JSON.stringify(original.words)&&JSON.stringify(M.words(text))===JSON.stringify(M.words(clip.dataset.subtitleText));return {mode:$('#karaokeMode').value,color:$('#karaokeColor').value,offset,lastMode:original?.lastMode,words:structuredClone(words),syncMarks:same&&original.syncMarks?structuredClone(original.syncMarks):undefined,syllables:same&&original.syllables?structuredClone(original.syllables):undefined};}
  function check(){try{M.validate({subtitleText:text,subtitleStyle:{karaoke:value()}});$('#karaokeError').textContent='';return true;}catch(e){$('#karaokeError').textContent=e.message;return false;}}
  function clock(){const seek=$('#karaokeSeek');seek.max=duration();$('#karaokeClock').textContent=position().toFixed(3)+' / '+duration().toFixed(3)+' s';}
  function stop(){stopTimelinePlayback();cancelAnimationFrame(frame);$('#karaokeListen').textContent='▶ Escuchar proyecto';}
  function follow(){if(closed)return;const local=timelineTime-Number($('#subStart').value);$('#karaokeSeek').value=Math.max(0,Math.min(duration(),local));clock();repaint();if(local>=duration()||!playing){stop();return;}frame=requestAnimationFrame(follow);}
  $('#karaokeListen').onclick=async()=>{if(playing){stop();return;}timelineTime=Number($('#subStart').value)+(position()>=duration()?0:position());await renderTimelineAt(timelineTime);if(closed)return;await startTimelinePlayback();if(closed){stopTimelinePlayback();return;}$('#karaokeListen').textContent='❚❚ Pausar';frame=requestAnimationFrame(follow);};
  $('#karaokeSeek').oninput=()=>{stop();clock();repaint();void renderTimelineAt(Number($('#subStart').value)+position());};
  $('#karaokeSpread').onclick=()=>{if(!confirm('¿Repartir de nuevo los tiempos de todas las palabras de este bloque? Se sustituirán los ajustes de sincronización.'))return;offset=0;words=M.seedWords(text,duration());next=0;rows();check();repaint();};
  $('#karaokeMark').onclick=()=>{if(next>=words.length){$('#karaokeError').textContent='Todas las entradas están marcadas. Puedes ajustar sus tiempos o repartirlos de nuevo.';return;}const t=position()+offset;if(next&&t<=words[next-1].start){$('#karaokeError').textContent='Avanza antes de marcar la siguiente palabra.';return;}if(t>=offset+duration()){ $('#karaokeError').textContent='La entrada debe quedar dentro del bloque.';return;}if(next)words[next-1].end=t;words[next].start=t;words[next].end=Math.max(t+.0001,next===words.length-1?offset+duration():words[next].end);next++;$('#karaokeMark').textContent=next<words.length?'Marcar: '+M.words(text)[next]:'Entradas marcadas';rows();check();repaint();};
  $('#karaokeWords').oninput=e=>{const input=e.target;if(!input.dataset.edge)return;words[Number(input.dataset.index)][input.dataset.edge]=Number(input.value)+offset;lane();check();repaint();};
  $('#karaokeLane').onpointerdown=e=>{if(e.button!==0)return;const target=e.target.closest('.karaoke-word');if(!target)return;e.preventDefault();stop();const i=Number(target.dataset.index),edge=e.target.dataset.edge,initial={...words[i]},x=e.clientX,width=$('#karaokeLane').getBoundingClientRect().width,low=Math.max(0,offset,i?words[i-1].end:0),high=Math.min(offset+duration(),i+1<words.length?words[i+1].start:Infinity),epsilon=Math.min(.001,(initial.end-initial.start)/2);const move=event=>{const delta=(event.clientX-x)/width*duration();if(edge==='start')words[i].start=Math.min(initial.end-epsilon,Math.max(low,initial.start+delta));else if(edge==='end')words[i].end=Math.max(initial.start+epsilon,Math.min(high,initial.end+delta));else{const shift=Math.max(low-initial.start,Math.min(high-initial.end,delta));words[i]={start:initial.start+shift,end:initial.end+shift};}rows();check();repaint();};const finish=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',cancel);dragCleanup=null;};const cancel=()=>{words[i]=initial;finish();rows();repaint();};dragCleanup=cancel;window.addEventListener('pointermove',move);window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',cancel);};
  const textChanged=()=>{const updated=$('#subText').value;if(updated===text)return;const same=JSON.stringify(M.words(updated))===JSON.stringify(M.words(text));text=updated;if(!same){offset=0;words=M.seedWords(text,duration());next=0;$('#karaokeError').textContent='Texto modificado: tiempos repartidos de nuevo. Revisa la sincronización.';}rows();};
  $('#subText').addEventListener('input',textChanged);
  $('#subDuration').addEventListener('input',()=>{clock();lane();});
  $('#karaokeMode').onchange=()=>{$('#karaokeTiming').hidden=$('#karaokeMode').value==='normal';if($('#karaokeTiming').hidden)stop();repaint();};
  $('#karaokeMode').onchange();rows();clock();
  dialog.addEventListener('close',()=>{closed=true;dragCleanup?.();stop();void renderTimelineAt(timelineTime);},{once:true});
  return {value:()=>{textChanged();return value();},time:position};
}
